function trx(k){return (extraTranslations[currentLang]||extraTranslations.en)[k]||k}
function loginAdmin(e){e.preventDefault();if($('#loginUser').value==='dark'&&$('#loginPass').value==='wear5555'){sessionStorage.setItem('darkios_auth','1');$('#loginScreen').style.display='none';$('#adminApp').style.display='flex';$('#loginError').textContent='';notify(trx('loginSuccess'))}else{$('#loginError').textContent=trx('loginError')}}
function logoutAdmin(){sessionStorage.removeItem('darkios_auth');$('#adminApp').style.display='none';$('#loginScreen').style.display='grid';$('#loginPass').value=''}
function globalKeys(mode){if(mode==='pause'){records.forEach(r=>{if(!banned.some(b=>b.key===r.key)){r.status='Inactive';r.manualStatus='GlobalPaused'}});log('Global key pause','All non-banned keys paused');notify(trx('allPaused'))}else{records.forEach(r=>{let isBanned=banned.some(b=>b.key===r.key);if(!isBanned&&r.manualStatus!=='ManualPaused'&&(!r.expiresAt||r.expiresAt>Date.now())){r.status='Active';r.manualStatus='Active'}});log('Global key activation','Eligible keys activated');notify(trx('allActive'))}persist();renderAll()}
function runBulk(){let f=$('#bulkFilter').value,a=$('#bulkAction').value;let list=records.filter(r=>!banned.some(b=>b.key===r.key)&&(f==='all'||f==='active'&&r.status==='Active'||f==='inactive'&&r.status!=='Active'||f==='tester'&&r.type==='TESTER'||f==='normal'&&(r.type==='NORMAL'||r.type==='Standard')));list.forEach(r=>{if(a==='pause'){r.status='Inactive';r.manualStatus='ManualPaused'}else if(a==='activate'){r.status='Active';r.manualStatus='Active'}else if(a==='extend'){r.expiresAt=(r.expiresAt&&r.expiresAt>Date.now()?r.expiresAt:Date.now())+7*86400000}else if(a==='delete'){records=records.filter(x=>x.id!==r.id)}});persist();log('Bulk operation',a+' · '+list.length+' keys');$('#bulkResult').textContent=trx('bulkDone')+': '+list.length;renderAll()}
function openIpBan(){modal(trx('ipBanTitle'),`<div class="field"><label>${trx('ipAddress')}</label><input id="newBanIp" placeholder="203.0.113.10"></div><div class="field"><label>${trx('reason')}</label><input id="newBanReason" placeholder="Abuse / policy violation"></div><div class="field"><label>${trx('duration')}</label><select id="newBanDuration"><option value="0">${trx('permBan')}</option><option value="3600000">1 hour</option><option value="86400000">1 day</option><option value="604800000">7 days</option><option value="2592000000">30 days</option></select></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">${trx('cancel')}</button><button class="create" onclick="saveIpBan()">${trx('ban')}</button></div>`)}
function saveIpBan(){let ip=$('#newBanIp').value.trim();if(!ip)return;let dur=+$('#newBanDuration').value;deviceBans.unshift({id:uid(),ip,deviceId:ip,reason:$('#newBanReason').value||'Admin IP ban',created:Date.now(),until:dur?Date.now()+dur:null});deviceSessions.filter(d=>(d.ip||d.deviceId)===ip).forEach(d=>d.status='Banned');persist();log('IP banned',ip);closeModal();renderAll();notify(trx('ipBanned'))}
function renderExtraViews(){
 if($('#expiryRows')){$('#expiryRows').innerHTML=records.filter(r=>r.expiresAt).map(r=>`<tr><td>${esc(r.key.slice(0,6)+'…'+r.key.slice(-6))}</td><td>${esc(r.type)}</td><td>${new Date(r.expiresAt).toLocaleString()}</td><td>${remaining(r)}</td><td><button class="secondary" onclick="editExpiry('${r.id}')">${trx('editExpiry')}</button></td></tr>`).join('')||'<tr><td colspan="5" class="blank">No expiring keys</td></tr>'}
 if($('#expiryCards'))$('#expiryCards').innerHTML=[['Expiring in 24h',records.filter(r=>r.expiresAt&&r.expiresAt>Date.now()&&r.expiresAt<Date.now()+86400000).length],['Expired',records.filter(r=>r.status==='Expired').length],['Lifetime',records.filter(r=>!r.expiresAt).length]].map(x=>`<div class="metric"><div class="label">${x[0]}</div><strong>${x[1]}</strong></div>`).join('');
 if($('#ipBanRows'))$('#ipBanRows').innerHTML=deviceBans.map(b=>`<tr><td>${esc(b.ip||b.deviceId)}</td><td>${esc(b.reason||'')}</td><td>${new Date(b.created).toLocaleString()}</td><td>${b.until?new Date(b.until).toLocaleString():trx('permBan')}</td><td><button class="secondary" onclick="removeIpBan('${b.id}')">${trx('remove')}</button></td></tr>`).join('')||'<tr><td colspan="5" class="blank">No banned IPs</td></tr>';
 if($('#notificationRows'))$('#notificationRows').innerHTML=logs.slice(0,100).map(l=>`<tr><td>${esc(l.event)}</td><td>${esc(l.detail)}</td><td>${esc(l.time)}</td><td>●</td></tr>`).join('')||'<tr><td colspan="4" class="blank">No notifications</td></tr>';
 if($('#templateGrid'))$('#templateGrid').innerHTML=(JSON.parse(localStorage.getItem('darkios_templates')||'[]')).map((t,i)=>`<div class="setting-card"><h3>${esc(t.name)}</h3><p>${esc(t.type)} · ${esc(t.duration)} · ${esc(t.devices)} device slot(s)</p><button class="secondary" onclick="useTemplate(${i})">Use preset</button> <button class="secondary" onclick="deleteTemplate(${i})">Delete</button></div>`).join('')||'<div class="setting-card">No saved templates yet.</div>';
 if($('#systemGrid'))$('#systemGrid').innerHTML=`<div class="setting-card"><h3>Local data usage</h3><p>${records.length} keys · ${banned.length} banned · ${deviceSessions.length} IP sessions</p><button class="secondary" onclick="backupJson()">Export backup</button></div><div class="setting-card"><h3>Refresh expiry states</h3><p>Recalculate expired and active key statuses.</p><button class="secondary" onclick="updateExpired();renderAll()">Run check</button></div><div class="setting-card"><h3>Sign out</h3><p>Close the current local administrator session.</p><button class="secondary" onclick="logoutAdmin()">${trx('logout')}</button></div><div class="setting-card"><h3>Clear demo IP sessions</h3><p>Removes all currently active IP bindings, not key bans.</p><button class="secondary" onclick="kickEveryDevice()">Reset all active IPs</button></div>`;
}
function removeIpBan(id){deviceBans=deviceBans.filter(b=>b.id!==id);persist();renderAll()}
function markNotificationsRead(){logs=logs.map(l=>({...l,read:true}));persist();renderExtraViews();notify(trx('saved'))}
function saveTemplate(){let arr=JSON.parse(localStorage.getItem('darkios_templates')||'[]');arr.push({name:'Preset '+(arr.length+1),type:'NORMAL',duration:'1D',devices:1});localStorage.setItem('darkios_templates',JSON.stringify(arr));renderExtraViews()}
function useTemplate(i){let t=JSON.parse(localStorage.getItem('darkios_templates')||'[]')[i];if(!t)return;openCreate();$('#newType').value=t.type;$('#newDeviceLimit').value=t.devices;notify('Preset loaded')}
function deleteTemplate(i){let a=JSON.parse(localStorage.getItem('darkios_templates')||'[]');a.splice(i,1);localStorage.setItem('darkios_templates',JSON.stringify(a));renderExtraViews()}

